<?php require '../includes/auth.php';require_role('seller');$sid=seller_profile_id(user()['id']);$s=db()->prepare('SELECT * FROM seller_profiles WHERE id=?');$s->execute([$sid]);$profile=$s->fetch();$pdo=db();$counts=[];foreach(['products'=>'SELECT COUNT(*) FROM products WHERE seller_id=?','orders'=>"SELECT COUNT(*) FROM seller_orders WHERE seller_id=?",'sales'=>"SELECT COALESCE(SUM(subtotal),0) FROM seller_orders WHERE seller_id=? AND status='Delivered'"] as $k=>$q){$x=$pdo->prepare($q);$x->execute([$sid]);$counts[$k]=$x->fetchColumn();}$pageTitle='Seller dashboard';require '../includes/header.php';?><div class="dashboard-hero"><p class="eyebrow">SELLER DASHBOARD</p><h1><?=e($profile['shop_name'])?></h1><?php if($profile['approval_status']!=='approved'):?><p class="flash error">Your shop is <?=e($profile['approval_status'])?>. You may set up listings, but they cannot go live until approval.</p><?php else:?><p>Keep today’s availability current and fulfill incoming orders.</p><?php endif;?><a class="button" href="<?=url('seller/add-product.php')?>">Add fish listing</a></div><section class="stats"><div><small>Active listings</small><strong><?=$counts['products']?></strong></div><div><small>Seller orders</small><strong><?=$counts['orders']?></strong></div><div><small>Delivered sales</small><strong>₹<?=number_format($counts['sales'],0)?></strong></div></section><section class="quick-links"><a href="<?=url('seller/products.php')?>">🐟<b>My listings</b><span>Add, edit availability and stock</span></a><a href="<?=url('seller/orders.php')?>">📦<b>Incoming orders</b><span>Accept and update fulfillment</span></a><a href="<?=url('seller/profile.php')?>">⚓<b>Shop profile</b><span>Update shop information</span></a></section><?php require '../includes/footer.php'; ?>
